import{z as s,x as B,o as e,c as i,q as E,j as t,D as a,d as A,s as n,S as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"Grok-1 开源 MoE","description":"","frontmatter":{"title":"Grok-1 开源 MoE","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/grok-1.md","filePath":"llm/grok-1.md","lastUpdated":1791413859000}'),p={name:"llm/grok-1.md"};function k(d,o,c,m,g,h){const r=B("Mermaid");return e(),i("div",null,[o[2]||(o[2]=E('<h1 id="grok-1-开源-moe" tabindex="-1">Grok-1 开源 MoE <a class="header-anchor" href="#grok-1-开源-moe" aria-label="Permalink to &quot;Grok-1 开源 MoE&quot;">​</a></h1><div class="epigraph"><p>我们发布 Grok-1 的权重与网络结构：这是一个 3140 亿参数的混合专家模型，给定 token 上约 25% 的权重被激活。</p><footer>—— xAI，Open Release of Grok-1，2024 年 3 月 17 日</footer></div><p>Grok-1 是 xAI 第一次把检查点放到公开许可证下：Apache 2.0、预训练结束于 2023 年 10 月的<strong>基座</strong>、JAX 参考加载代码。稀疏图案（8 专家、每 token 2 个、约 25% 激活）在 <a href="/llm/grok-moe">Grok MoE 公开信息</a> 里按路由口径写过；本篇把对象换成<strong>这份开源文物本身</strong>——仓库声明了什么、检查点不是什么、词表与注意力如何从 README 直接算出来、社区转换相对官方 JAX 权重处在哪一层。专家内部维、训练 token、负载损失是否存在，公告没写的一律标<strong>公开信息有限</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>2024 年春天，开源侧已有 Mixtral 一类「少专家 top-2」，但总参数停在几十亿到百亿量级。xAI 要公开的是当时最大的 MoE 权重之一，同时明确：<strong>这不是 X 上那个会聊天的 Grok</strong>。若把产品人格、实时检索和这份 314B 基座当成同一个分布，所有评测都会错。问题因此分成两半：结构表里哪些数字可以当一等来源；参考实现故意不追求效率，意味着「能加载」不等于「能当生产推理」。</p><p>第二个问题是许可证与栈。Apache 2.0 覆盖源码与 Grok-1 权重，允许商用与再分发，但训练数据、对齐配方、自定义 JAX/Rust 工具链并不随仓库出现。能复现的是前向形状，不是预训练。</p><h3 id="一等来源止于公告、readme-与官方权重" tabindex="-1">一等来源止于公告、README 与官方权重 <a class="header-anchor" href="#一等来源止于公告、readme-与官方权重" aria-label="Permalink to &quot;一等来源止于公告、README 与官方权重&quot;">​</a></h3><p>可核对材料主要是：2024-03-17 的开源公告、GitHub <code>xai-org/grok-1</code>、Hugging Face <code>xai-org/grok-1</code> 的 JAX 检查点。公告写明：从零训练的 314B MoE；给定 token 约 25% 权重激活；基座未做对话微调；训练栈建立在 JAX 与 Rust 之上。仓库补充结构常数，并警告 MoE 层<strong>不为效率而写</strong>，只为在不依赖自定义核的前提下校验正确性。第三方 PyTorch 转换、量化包、评测榜是二等来源：层名一改，分数就不能自动算作官方数字。</p><p><span class="marginnote">314B 是总参数。25% 与「8 选 2」在算术上一致，但公告给的是激活比例，仓库给的是专家个数。对齐着读即可，不要再发明第三套 \\(k\\)。路由机制见 <a href="/llm/grok-moe">Grok MoE</a>。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>官方规格可收成一张短表，全部来自仓库当时的说明：总参数 314B；<strong>8 专家 MoE，每 token 用 2 个</strong>；<strong>64 层</strong>；注意力 <strong>48 个查询头、8 个键值头</strong>（<a href="/llm/gqa">GQA</a>）；嵌入宽度 <strong>6144</strong>；词表 <strong>131,072</strong> 的 SentencePiece；位置编码 RoPE；支持激活切分与 8-bit 量化。最大序列长度常见转述为 8,192，若与某次镜像冲突，仍以官方 README 为准。头维可以直接算：\\(d_k=6144/48=128\\)。KV 缓存体积相对完整多头是 \\(8/48=1/6\\)。这些是公开数字的推论，不必另找论文——xAI 没有为 Grok-1 单独发技术报告，也<strong>不要编造 arXiv 编号</strong>。</p><p><span class="marginnote">数字实例：嵌入宽度 6144、48 个查询头，所以每个头的维度是 \\(6144 \\div 48 = 128\\)。键值头只有 8 个，相当于 48 个查询头分成 8 组、每组共享同一份 K/V，KV 缓存因此缩到完整多头的 \\(8/48 \\approx 17\\%\\)，长序列下的显存压力小得多。</span></p><h3 id="参考实现是校验器-不是推理引擎" tabindex="-1">参考实现是校验器，不是推理引擎 <a class="header-anchor" href="#参考实现是校验器-不是推理引擎" aria-label="Permalink to &quot;参考实现是校验器，不是推理引擎&quot;">​</a></h3><p>仓库用 Haiku / JAX 搭 Transformer 与 MoE，路由做 token-choice 的 top-2，专家计算走 <code>shard_map</code> 一类切分。作者自己说这份 MoE 慢，目的是避免为了速度写自定义核而把数值弄错。因此不能拿仓库吞吐去外推 Colossus 或产品 Grok 的服务栈。要真正跑 314B，需要专家并行、分组 GEMM 或现成框架，那已经是实现选择。8-bit 列在附加特性里，更像推理可按 8-bit 加载，不是一份量化感知训练配方；校准集与是否逐专家标定，公开信息有限。</p>',14)),(e(),t(l,null,{default:a(()=>[n(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20CKPT%5B%22%E5%AE%98%E6%96%B9%20JAX%20%E6%A3%80%E6%9F%A5%E7%82%B9%20ckpt-0%22%5D%20--%3E%20LOAD%5B%22%E4%BB%93%E5%BA%93%E5%8A%A0%E8%BD%BD%E7%A4%BA%E4%BE%8B%22%5D%0A%20%20LOAD%20--%3E%20SP%5B%22SentencePiece%20131072%22%5D%0A%20%20SP%20--%3E%20DEC%5B%2264%20%E5%B1%82%E8%A7%A3%E7%A0%81%E5%99%A8%22%5D%0A%20%20DEC%20--%3E%20GQA%5B%2248%20Q%20%E5%A4%B4%20%2F%208%20KV%20%E5%A4%B4%20%2B%20RoPE%22%5D%0A%20%20DEC%20--%3E%20EXP%5B%228%20%E4%B8%93%E5%AE%B6%20FFN%EF%BC%8Ctop-2%22%5D%0A%20%20LOAD%20--%3E%20CONV%5B%22%E7%A4%BE%E5%8C%BA%20PyTorch%20%2F%20HF%20%E8%BD%AC%E6%8D%A2%22%5D%0A%20%20CONV%20--%3E%20DISC%5B%22%E4%BA%8C%E7%AD%89%E6%9D%A5%E6%BA%90%EF%BC%9A%E4%BB%A5%E5%8E%9F%E6%A3%80%E6%9F%A5%E7%82%B9%E4%B8%BA%E5%87%86%22%5D%0A"})]),fallback:a(()=>[...o[0]||(o[0]=[A(" Loading... ",-1)])]),_:1})),o[3]||(o[3]=E('<p>检查点是预训练结束快照。用它直接聊天，行为与 grok.x.ai 不可比；要对话必须自己做 SFT / 偏好学习，那部分数据与超参不在开源包里。许可是 Apache 2.0，这一点与后来许多「研究向、非商用」权重不同，也是这份发布在生态里被反复引用的原因之一。</p><p><span class="marginnote">常见误区：有人下载 Grok-1 直接提问，发现它「答非所问」，就断定模型不行。其实这是基座（base model）的正常表现——它只学过续写文本，没学过对话指令。要能聊天必须再做 SFT / 偏好学习，而这份配方没有随权重开源。</span></p><p><span class="marginnote">Hugging Face 上的官方仓库是权重托管，不是第二份架构声明。转换脚本若合并专家、改层名或重写成别的 MoE 接口，应视为衍生工件。数值争议时回到 JAX 原检查点。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>在已公开设定下，前向并不神秘：注意力是带 GQA 与 RoPE 的标准解码器块，FFN 换成 8 路专家。稀疏发生在 FFN，不发生在 KV——把「314B MoE」读成「注意力也稀疏」没有根据。组合数 \\(\\binom{8}{2}=28\\)，容量主要来自每个专家的宽度与 64 层堆叠，而不是组合爆炸。与 Mixtral 相同的是少专家 top-2，不同的是层宽、层数与总参数差出一个数量级；与 DeepSeek 式细粒度 MoE 只共享「FFN 稀疏」这一句。对照口径见 <a href="/llm/grok-moe">Grok MoE</a>。</p><p><span class="marginnote">「8 选 2 的 MoE」翻译一下：每层前馈网络被复制成 8 份「专家」，每个 token 只挑路由得分最高的 2 份来算。类比医院分诊：病人只挂 2 个专科，不必把 8 个科室全跑一遍——省的是计算量，不是占的显存，8 份专家权重仍然全部要装进机器。</span></p>',6)),(e(),t(l,null,{default:a(()=>[n(r,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E4%B8%80%E4%B8%AA%20token%20%E8%BF%9B%20MoE%20%E5%B1%82%22%5D%20--%3E%20ATT%5B%22%E6%B3%A8%E6%84%8F%E5%8A%9B%EF%BC%9A48%20Q%20%E5%A4%B4%E5%85%A8%E8%B7%91%EF%BC%8C%E4%B8%8D%E7%A8%80%E7%96%8F%22%5D%0A%20%20ATT%20--%3E%20ROU%5B%22%E8%B7%AF%E7%94%B1%E5%99%A8%E7%BB%99%208%20%E4%B8%AA%E4%B8%93%E5%AE%B6%E6%89%93%E5%88%86%22%5D%0A%20%20ROU%20--%3E%20E1%5B%22%E5%BE%97%E5%88%86%E7%AC%AC%201%20%E7%9A%84%E4%B8%93%E5%AE%B6%EF%BC%9A%E5%AE%8C%E6%95%B4%E8%AE%A1%E7%AE%97%22%5D%0A%20%20ROU%20--%3E%20E2%5B%22%E5%BE%97%E5%88%86%E7%AC%AC%202%20%E7%9A%84%E4%B8%93%E5%AE%B6%EF%BC%9A%E5%AE%8C%E6%95%B4%E8%AE%A1%E7%AE%97%22%5D%0A%20%20ROU%20--%3E%20E3%5B%22%E5%85%B6%E4%BD%99%206%20%E4%B8%AA%E4%B8%93%E5%AE%B6%EF%BC%9A%E6%9C%AC%20token%20%E8%B7%B3%E8%BF%87%22%5D%0A%20%20E1%20--%3E%20SUM%5B%22%E4%B8%A4%E8%B7%AF%E8%BE%93%E5%87%BA%E5%8A%A0%E6%9D%83%E5%90%88%E5%B9%B6%22%5D%0A%20%20E2%20--%3E%20SUM%0A%20%20SUM%20--%3E%20NX%5B%22%E8%BF%9B%E4%B8%8B%E4%B8%80%E5%B1%82%22%5D%0A"})]),fallback:a(()=>[...o[1]||(o[1]=[A(" Loading... ",-1)])]),_:1})),o[4]||(o[4]=E('<p>词表 131k 的 SentencePiece 决定切词与嵌入矩阵形状。没有公开 BPE 与 tiktoken 的并排压缩率，不能把「大词表一定更省长度」写成 Grok-1 的实验结果。8k 窗口是这份基座的训练/推理上限（以 README 为准），后续产品拉到 128k 不能回写到 2023 年 10 月的检查点上。</p><h3 id="激活量只说明前向-flop-量级" tabindex="-1">激活量只说明前向 FLOP 量级 <a class="header-anchor" href="#激活量只说明前向-flop-量级" aria-label="Permalink to &quot;激活量只说明前向 FLOP 量级&quot;">​</a></h3><p>和稠密 314B 比，一次前向大约只跑四分之一专家权重，外加全部注意力与嵌入。和「激活约 80B 量级」的心算可以做，但精确激活参数若仓库没写，就不要当成官方规格。Decode 仍受 64 层 KV 带宽约束；GQA 只把 KV 头降到 8，长度一长仍然贵。参考实现的激活切分是为了把大激活放进多设备，不是算法创新。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>材料边界是硬的。没有官方技术报告，任何「Grok-1 为何有效」的因果叙事都超出公开文本。语料构成、学习率、专家容量因子、是否用辅助负载损失，公开信息有限。产品线 Grok-1.5 / 2 / 3 的上下文、工具与思考模式，见 <a href="/llm/grok-2-3">Grok-2 / Grok-3 公开信息</a>，不得用 8×top-2 去填后续代际。</p><p>工程上，314B 即使用 25% 激活，也不是单卡或端侧模型。开源的价值主要是：可审计的结构常数、可下载的基座、宽松许可。把它当聊天机器人，缺的是后训练；把它当 MoE 系统论文，缺的是消融。社区量化与蒸馏是下游工作，误差与数据都不由 xAI 背书。</p><p><span class="marginnote">「当时最大的开源 MoE」是发布时点的历史描述，随后会被别的权重超过。写文章应钉 2024-03-17，而不是把头衔当成永久属性。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>xAI 于 2024 年 3 月 17 日开源 Grok-1：314B MoE 基座、Apache 2.0、预训练结束于 2023 年 10 月，未做对话微调。</li><li>可核对结构：64 层，嵌入 6144，48/8 GQA，RoPE，131k SentencePiece，8 专家 top-2；上下文以官方 README 的 8k 量级为准。</li><li>参考实现只为正确性；训练栈 JAX+Rust 的细节、数据与优化器公开信息有限。</li><li>产品 Grok ≠ 开源 Grok-1；MoE 路由对照见 <a href="/llm/grok-moe">Grok MoE</a>；后续代际见 <a href="/llm/grok-2-3">Grok-2 / 3</a>。</li><li>出处：xAI，<em>Open Release of Grok-1</em>（2024-03-17）；GitHub <code>xai-org/grok-1</code>。不编造技术报告或 arXiv 编号。</li></ul>',9))])}const u=s(p,[["render",k]]);export{_ as __pageData,u as default};
